import React from "react";
import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  getDogs,
  chargeAll,
 getTemperaments,
 filterBy,
 orderBy,
 filterTemperament,
} from "../redux/actions/index";
import { Link } from "react-router-dom";
import Card from "../components/Card";
import Pagination from "../components/Pagination";
import SearchBar from "../components/SearchBar";
import styles from "../styles/Home.module.css";


const HomePage = ({paginate}) => {
  const dispatch = useDispatch();

  //para manipular los states
  const allDog = useSelector((state) => state.dogs);
  const temperament = useSelector((state)=> state.temperaments);

  const temperamentsOrder = temperament.sort((a, b) => { //se ordena alfabeticamente para que salga bien en el select
    if (a.name > b.name) { return 1; }
    if (a.name < b.name) { return -1;}
    return 0;
  })


  // Creamos un state con la pagina actual y otro que haga set
  const [currentPage, setCurrentPage] = useState(1);
  const [DogPerPage, setDogPerPage] = useState(8); //asi mostramos 12 por pagina
  const indexLastDog = currentPage * DogPerPage;
  const indexFirstDog = indexLastDog - DogPerPage;
  //para marcar la distancia el slice parte a la mitad.
  const currentDog = allDog.slice(indexFirstDog, indexLastDog);
  //para setear la pagina en ese numero de pagina. Helps with rendering
  const paging = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  // se va a ejecutar cada vez que ocurra dispatch como en el did mount >// vacio no depende de nada
  useEffect(() => {
    dispatch(getDogs());
    dispatch(getTemperaments());
  }, [dispatch]); //otherwise loop

  function handleClick(e) {
    e.preventDefault(); // para que no se rompa. Just in case.
    dispatch(getDogs());
    setCurrentPage(1);
  }

 const onFilterTemperament = (e) => {
  e.preventDefault()
  dispatch(filterTemperament(e.target.value))
  paginate(1)
  };

  const handleSelect2 = (e) => {
    dispatch(orderBy(e.target.value))
  };

  return (
    <div>

      <nav>
        <div className={styles.search}>
          <SearchBar />
        </div>

        <div>
          <Link to="/createDog">
            <button className={styles.btn}>Crear Perrito</button>
          </Link>
        </div>
        </nav>

        <div className={`${styles.filter}`}>
        
        <select onChange={handleSelect2}>
        <option defaultValue>Order By</option>
                <option value={A_Z}>Order A - Z</option>
                <option value={Z_A}>Order Z - A</option>
                <option value={WEIGHT_MAX}>Weight Max</option>
                <option value={WEIGHT_MIN}>Weight Min</option>
            </select>

        <div>
            <select onChange={onFilterTemperament} className={styles.select}>
                <option value='All Temperaments' key='All Temperaments'>All Temperaments</option>
                {temperamentsOrder.map((el, index)=> (
                    <option value={el.name} key={index}>{el.name}</option>
                ))}
            </select>
        </div>

        <button value="TODOS" onClick={() => dispatch(chargeAll())}>
            ALL
          </button>
          <button value="DB" onClick={() => dispatch(filterBy("DB"))}>
            DATABASE
          </button>
          <button value="API" onClick={() => dispatch(filterBy("API"))}>
            API
          </button>
      </div>

      {/* cambiamos a current */}
      <div className={`${styles.card} ${styles.cardContainer}`}>
        {/* cambiamos al current para que aparezcan los que quiero */}
        {currentDog.length === 0 ? (
          <img className={styles.image} alt="No hay perritos"></img>
        ) : (
          currentDog.map((c) => {
            return (
              <div className={styles.cardFormat} key={c.id}>
                <Link className={styles.name} to={"/dogs" + c.id}>
                  <Card
                    name={c.name}
                    image={c.image}
                    weightMin={c.weightMin}
                    weightMax={c.weightMax}                    
                    temperament={c.temperament}
                    />
                </Link>
              </div>
            );
          })
        )}

       
      </div>

    
      <div className={styles.pagination}>
        <Pagination
          DogPerPage={DogPerPage}
          allDog={allDog.length}
          paging={paging}
        />
      </div>
    </div>
  );
};

export default HomePage;
